import{_ as a,c as e,o as i,V as l}from"./chunks/framework.tJhZUYt7.js";const m=JSON.parse('{"title":"一、Java主类结构","description":"","frontmatter":{},"headers":[],"relativePath":"rear/java/Java基础语法/Java主类结构.md","filePath":"rear/java/Java基础语法/Java主类结构.md","lastUpdated":1719821588000}'),o={name:"rear/java/Java基础语法/Java主类结构.md"},t=l('<h1 id="一、java主类结构" tabindex="-1">一、Java主类结构 <a class="header-anchor" href="#一、java主类结构" aria-label="Permalink to &quot;一、Java主类结构&quot;">​</a></h1><ol><li>Java中使用类----关键字class来定义对象的类型</li><li>如果是这个类成为独立运行的程序，必须包含名为<code>main()</code>的方法，此时这个类也称为<code>主类</code></li><li>一个类只能有一个主方法，但是可以定义多个方法</li><li>Java对大小写很敏感</li><li>在命名主类名称时，须注意大小写，第一个字母须大写，同时主类名称要与文件名称保持一致</li></ol><h2 id="一、java包" tabindex="-1">一、Java包 <a class="header-anchor" href="#一、java包" aria-label="Permalink to &quot;一、Java包&quot;">​</a></h2><p>包（package）格式</p><div class="language-java vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">package</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> com._01kuaixue.java</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ol><li>实际开发中，把功能相同或相近的类文件放在同一个包下，使用不同的包声明对各个程序文件进行保存、管理和隔离</li><li>包的声明放在文件第一行</li></ol><h3 id="import" tabindex="-1">import <a class="header-anchor" href="#import" aria-label="Permalink to &quot;import&quot;">​</a></h3><p>为了引入某个包特定的内容</p><div class="language-java vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> com._01.kuaixue.java.MainClass</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><blockquote><p>import声明必须在package包声明之后，类声明之前</p></blockquote><h2 id="二、类的成员变量和局部变量" tabindex="-1">二、类的成员变量和局部变量 <a class="header-anchor" href="#二、类的成员变量和局部变量" aria-label="Permalink to &quot;二、类的成员变量和局部变量&quot;">​</a></h2><ul><li>成员变量：类中直接声明的属性</li><li>局部变量：在方法中声明的属性</li><li>成员变量能够在类中各个地方调用，而局部变量只能在声明的方法中使用</li></ul><h2 id="三、访问权限修饰词" tabindex="-1">三、访问权限修饰词 <a class="header-anchor" href="#三、访问权限修饰词" aria-label="Permalink to &quot;三、访问权限修饰词&quot;">​</a></h2><p>Java提供了public、private、proteced三种访问权限修饰词，在类文件中每个成员定义之前，每个修饰词都定义了成员不同的访问权限。</p><ul><li>当不写以上三种修饰词时，Java会默认该类的访问权限为<code>包访问权限</code>，即这个包路径下的其他类文件都可以访问该类</li><li><code>公开访问权限</code>--<code>public</code>。public标识该类或成员变量、成员函数对其他所有类文件都是开放的，其他类文件(不论是否在该文件的包目录下)都可以直接进行调用，调用时只需用import关键字引人即可</li><li><code>私有访问权限</code>--<code>private</code>。private标识该成员变量、成员函数只可以在自己的类文件内使用,其他任何的类文件都无法访问和使用这个变量或函数。这也意味着，即使是同一个包下的其他文件，也是无法访问的</li><li><code>继承访问权限</code>--<code>protected</code>。如果一个类A继承了另一个类B，那么B类是A类的父类，A类是B类的子类，此时B类如果定义了一个<code>protected</code>的变量，这个变量<strong>可以在A类中使用，也可以被B类所在的包使用</strong>，但这个变量无法被其他类使用</li></ul><h2 id="四、编写主方法" tabindex="-1">四、编写主方法 <a class="header-anchor" href="#四、编写主方法" aria-label="Permalink to &quot;四、编写主方法&quot;">​</a></h2><ul><li>每个Java应用程序都必须有且仅有一个<code>main主方法</code>，程序从“(”开始运行，到“}”结束运行</li><li><code>main()</code>主方法必须被声明为<strong>public static void</strong>，并且入参，必须是<code>Sting[] args</code>或<code>Sting args[]</code></li><li><code>main()</code>方法之所以是<code>public</code>，是因为每个Java程序在运行时都要创建一个Java虚拟机（全称JavaVinual Machine，简称JVM实例），由JVM从外部调用<code>main()</code>方法就需要公开访问权限，所以必须要用public声明</li><li><code>void</code>表示main()方法没有具体返回值</li><li><code>static</code>关键字可修饰类的属性和方法，被static修饰的成员被称作“静态成员”（或静态属性、静态方法）</li></ul>',17),s=[t];function c(d,r,n,p,h,u){return i(),e("div",null,s)}const b=a(o,[["render",c]]);export{m as __pageData,b as default};
